(function ($) {
    "use strict";
    if (!$.browser) {
        $.browser = {};
        $.browser.mozilla = /mozilla/.test(navigator.userAgent.toLowerCase()) && !/webkit/.test(navigator.userAgent.toLowerCase());
        $.browser.webkit = /webkit/.test(navigator.userAgent.toLowerCase());
        $.browser.opera = /opera/.test(navigator.userAgent.toLowerCase());
        $.browser.msie = /msie/.test(navigator.userAgent.toLowerCase());
    }

    var methods = {
        destroy: function () {
            $(this).unbind(".maskMoney");

            if ($.browser.msie) {
                this.onpaste = null;
            }
            return this;
        },

        applyMask: function (value) {
            var $input = $(this);
            // data-* api
            var settings = $input.data("settings");
            return maskValue(value, settings);
        },

        mask: function (value) {
            return this.each(function () {
                var $this = $(this);
                if (typeof value === "number") {
                    $this.val(value);
                }
                return $this.trigger("mask");
            });
        },

        unmasked: function () {
            return this.map(function () {
                var value = ($(this).val() || "0"),
                    isNegative = value.indexOf("-") !== -1,
                    decimalPart;
                // get the last position of the array that is a number(coercion makes "" to be evaluated as false)
                $(value.split(/\D/).reverse()).each(function (index, element) {
                    if (element) {
                        decimalPart = element;
                        return false;
                    }
                });
                value = value.replace(/\D/g, "");
                value = value.replace(new RegExp(decimalPart + "$"), "." + decimalPart);
                if (isNegative) {
                    value = "-" + value;
                }
                return parseFloat(value);
            });
        },

        init: function (parameters) {
            parameters = $.extend({
                prefix: "",
                suffix: "",
                affixesStay: true,
                thousands: ",",
                decimal: ".",
                precision: 2,
                allowZero: false,
                allowNegative: false,
                doubleClickSelection: true,
                allowEmpty: false
            }, parameters);

            return this.each(function () {
                var $input = $(this), settings,
                    onFocusValue;

                // data-* api
                settings = $.extend({}, parameters);
                settings = $.extend(settings, $input.data());

                // Store settings for use with the applyMask method.
                $input.data("settings", settings);


                function getInputSelection() {
                    var el = $input.get(0),
                        start = 0,
                        end = 0,
                        normalizedValue,
                        range,
                        textInputRange,
                        len,
                        endRange;

                    if (typeof el.selectionStart === "number" && typeof el.selectionEnd === "number") {
                        start = el.selectionStart;
                        end = el.selectionEnd;
                    } else {
                        range = document.selection.createRange();

                        if (range && range.parentElement() === el) {
                            len = el.value.length;
                            normalizedValue = el.value.replace(/\r\n/g, "\n");

                            // Create a working TextRange that lives only in the input
                            textInputRange = el.createTextRange();
                            textInputRange.moveToBookmark(range.getBookmark());

                            // Check if the start and end of the selection are at the very end
                            // of the input, since moveStart/moveEnd doesn't return what we want
                            // in those cases
                            endRange = el.createTextRange();
                            endRange.collapse(false);

                            if (textInputRange.compareEndPoints("StartToEnd", endRange) > -1) {
                                start = end = len;
                            } else {
                                start = -textInputRange.moveStart("character", -len);
                                start += normalizedValue.slice(0, start).split("\n").length - 1;

                                if (textInputRange.compareEndPoints("EndToEnd", endRange) > -1) {
                                    end = len;
                                } else {
                                    end = -textInputRange.moveEnd("character", -len);
                                    end += normalizedValue.slice(0, end).split("\n").length - 1;
                                }
                            }
                        }
                    }

                    return {
                        start: start,
                        end: end
                    };
                } // getInputSelection

                function canInputMoreNumbers() {
                    var haventReachedMaxLength = !($input.val().length >= $input.attr("maxlength") && $input.attr("maxlength") >= 0),
                        selection = getInputSelection(),
                        start = selection.start,
                        end = selection.end,
                        haveNumberSelected = (selection.start !== selection.end && $input.val().substring(start, end).match(/\d/)) ? true : false,
                        startWithZero = ($input.val().substring(0, 1) === "0");
                    return haventReachedMaxLength || haveNumberSelected || startWithZero;
                }

                function setCursorPosition(pos) {
                    // Do not set the position if
                    // the we're formatting on blur.
                    // This is because we do not want
                    // to refocus on the control after
                    // the blur.
                    if (!!settings.formatOnBlur) {
                        return;
                    }

                    $input.each(function (index, elem) {
                        if (elem.setSelectionRange) {
                            elem.focus();
                            elem.setSelectionRange(pos, pos);
                        } else if (elem.createTextRange) {
                            var range = elem.createTextRange();
                            range.collapse(true);
                            range.moveEnd("character", pos);
                            range.moveStart("character", pos);
                            range.select();
                        }
                    });
                }

                function maskAndPosition(startPos) {
                    var originalLen = $input.val().length,
                        newLen;
                    $input.val(maskValue($input.val(), settings));
                    newLen = $input.val().length;
                    // If the we're using the reverse option,
                    // do not put the cursor at the end of
                    // the input. The reverse option allows 
                    // the user to input text from left to right.
                    if (!settings.reverse) {
                        startPos = startPos - (originalLen - newLen);
                    }
                    setCursorPosition(startPos);
                }

                function mask() {
                    var value = $input.val();
                    if (settings.allowEmpty && value === "") {
                        return;
                    }
                    if (settings.precision > 0 && value.indexOf(settings.decimal) < 0) {
                        value += settings.decimal + new Array(settings.precision + 1).join(0);
                    }
                    $input.val(maskValue(value, settings));
                }

                function changeSign() {
                    var inputValue = $input.val();
                    if (settings.allowNegative) {
                        if (inputValue !== "" && inputValue.charAt(0) === "-") {
                            return inputValue.replace("-", "");
                        } else {
                            return "-" + inputValue;
                        }
                    } else {
                        return inputValue;
                    }
                }

                function preventDefault(e) {
                    if (e.preventDefault) { //standard browsers
                        e.preventDefault();
                    } else { // old internet explorer
                        e.returnValue = false;
                    }
                }

                function keypressEvent(e) {
                    e = e || window.event;
                    var key = e.which || e.charCode || e.keyCode,
                        decimalKeyCode = settings.decimal.charCodeAt(0);
                    //added to handle an IE "special" event
                    if (key === undefined) {
                        return false;
                    }

                    // any key except the numbers 0-9. if we're using settings.reverse,
                    // allow the user to input the decimal key
                    if ((key < 48 || key > 57) && (key !== decimalKeyCode || !settings.reverse)) {
                        return handleAllKeysExceptNumericalDigits(key, e);
                    } else if (!canInputMoreNumbers()) {
                        return false;
                    } else {
                        if (key === decimalKeyCode && shouldPreventDecimalKey()) {
                            return false;
                        }
                        if (settings.formatOnBlur) {
                            return true;
                        }
                        preventDefault(e);
                        applyMask(e);
                        return false;
                    }
                }

                function shouldPreventDecimalKey() {
                    // If all text is selected, we can accept the decimal
                    // key because it will replace everything.
                    if (isAllTextSelected()) {
                        return false;
                    }

                    return alreadyContainsDecimal();
                }

                function isAllTextSelected() {
                    var length = $input.val().length;
                    var selection = getInputSelection();
                    // This should if all text is selected or if the
                    // input is empty.
                    return selection.start === 0 && selection.end === length;
                }

                function alreadyContainsDecimal() {
                    return $input.val().indexOf(settings.decimal) > -1;
                }

                function applyMask(e) {
                    e = e || window.event;
                    var key = e.which || e.charCode || e.keyCode,
                        keyPressedChar = "",
                        selection,
                        startPos,
                        endPos,
                        value;
                    if (key >= 48 && key <= 57) {
                        keyPressedChar = String.fromCharCode(key);
                    }
                    selection = getInputSelection();
                    startPos = selection.start;
                    endPos = selection.end;
                    value = $input.val();
                    $input.val(value.substring(0, startPos) + keyPressedChar + value.substring(endPos, value.length));
                    maskAndPosition(startPos + 1);
                }

                function handleAllKeysExceptNumericalDigits(key, e) {
                    // -(minus) key
                    if (key === 45) {
                        $input.val(changeSign());
                        return false;
                        // +(plus) key
                    } else if (key === 43) {
                        $input.val($input.val().replace("-", ""));
                        return false;
                        // enter key or tab key
                    } else if (key === 13 || key === 9) {
                        return true;
                    } else if ($.browser.mozilla && (key === 37 || key === 39) && e.charCode === 0) {
                        // needed for left arrow key or right arrow key with firefox
                        // the charCode part is to avoid allowing "%"(e.charCode 0, e.keyCode 37)
                        return true;
                    } else { // any other key with keycode less than 48 and greater than 57
                        preventDefault(e);
                        return true;
                    }
                }

                function keydownEvent(e) {
                    e = e || window.event;
                    var key = e.which || e.charCode || e.keyCode,
                        selection,
                        startPos,
                        endPos,
                        value,
                        lastNumber;
                    //needed to handle an IE "special" event
                    if (key === undefined) {
                        return false;
                    }

                    selection = getInputSelection();
                    startPos = selection.start;
                    endPos = selection.end;

                    if (key === 8 || key === 46 || key === 63272) { // backspace or delete key (with special case for safari)
                        preventDefault(e);

                        value = $input.val();

                        // not a selection
                        if (startPos === endPos) {
                            // backspace
                            if (key === 8) {
                                if (settings.suffix === "") {
                                    startPos -= 1;
                                } else {
                                    // needed to find the position of the last number to be erased
                                    lastNumber = value.split("").reverse().join("").search(/\d/);
                                    startPos = value.length - lastNumber - 1;
                                    endPos = startPos + 1;
                                }
                                //delete
                            } else {
                                endPos += 1;
                            }
                        }

                        $input.val(value.substring(0, startPos) + value.substring(endPos, value.length));

                        maskAndPosition(startPos);
                        return false;
                    } else if (key === 9) { // tab key
                        return true;
                    } else { // any other key
                        return true;
                    }
                }

                function focusEvent() {
                    onFocusValue = $input.val();
                    mask();
                    var input = $input.get(0),
                        textRange;

                    if (!!settings.selectAllOnFocus) {
                        input.select();
                    } else if (input.createTextRange) {
                        textRange = input.createTextRange();
                        textRange.collapse(false); // set the cursor at the end of the input
                        textRange.select();
                    }
                }

                function cutPasteEvent() {
                    setTimeout(function () {
                        mask();
                    }, 0);
                }

                function getDefaultMask() {
                    var n = parseFloat("0") / Math.pow(10, settings.precision);
                    return (n.toFixed(settings.precision)).replace(new RegExp("\\.", "g"), settings.decimal);
                }

                function blurEvent(e) {
                    if ($.browser.msie) {
                        keypressEvent(e);
                    }

                    if (!!settings.formatOnBlur && $input.val() !== onFocusValue) {
                        applyMask(e);
                    }

                    if ($input.val() === "" && settings.allowEmpty) {
                        $input.val("");
                    } else if ($input.val() === "" || $input.val() === setSymbol(getDefaultMask(), settings)) {
                        if (!settings.allowZero) {
                            $input.val("");
                        } else if (!settings.affixesStay) {
                            $input.val(getDefaultMask());
                        } else {
                            $input.val(setSymbol(getDefaultMask(), settings));
                        }
                    } else {
                        if (!settings.affixesStay) {
                            var newValue = $input.val().replace(settings.prefix, "").replace(settings.suffix, "");
                            $input.val(newValue);
                        }
                    }
                    if ($input.val() !== onFocusValue) {
                        $input.change();
                    }
                }

                function clickEvent() {
                    var input = $input.get(0),
                        length;
                    if (!!settings.selectAllOnFocus) {
                        // selectAllOnFocus will be handled by 
                        // the focus event. The focus event is
                        // also fired when the input is clicked.
                        return;
                    } else if (input.setSelectionRange) {
                        length = $input.val().length;
                        input.setSelectionRange(length, length);
                    } else {
                        $input.val($input.val());
                    }
                }

                function doubleClickEvent() {
                    var input = $input.get(0),
                        start,
                        length;
                    if (input.setSelectionRange) {
                        length = $input.val().length;
                        start = settings.doubleClickSelection ? 0 : length;
                        input.setSelectionRange(start, length);
                    } else {
                        $input.val($input.val());
                    }
                }

                $input.unbind(".maskMoney");
                $input.bind("keypress.maskMoney", keypressEvent);
                $input.bind("keydown.maskMoney", keydownEvent);
                $input.bind("blur.maskMoney", blurEvent);
                $input.bind("focus.maskMoney", focusEvent);
                $input.bind("click.maskMoney", clickEvent);
                $input.bind("dblclick.maskMoney", doubleClickEvent);
                $input.bind("cut.maskMoney", cutPasteEvent);
                $input.bind("paste.maskMoney", cutPasteEvent);
                $input.bind("mask.maskMoney", mask);
            });
        }
    };

    function setSymbol(value, settings) {
        var operator = "";
        if (value.indexOf("-") > -1) {
            value = value.replace("-", "");
            operator = "-";
        }
        if (value.indexOf(settings.prefix) > -1) {
            value = value.replace(settings.prefix, "");
        }
        if (value.indexOf(settings.suffix) > -1) {
            value = value.replace(settings.suffix, "");
        }
        return operator + settings.prefix + value + settings.suffix;
    }

    function maskValue(value, settings) {
        if (settings.allowEmpty && value === "") {
            return "";
        }
        if (!!settings.reverse) {
            return maskValueReverse(value, settings);
        }
        return maskValueStandard(value, settings);
    }

    function maskValueStandard(value, settings) {
        var negative = (value.indexOf("-") > -1 && settings.allowNegative) ? "-" : "",
            onlyNumbers = value.replace(/[^0-9]/g, ""),
            integerPart = onlyNumbers.slice(0, onlyNumbers.length - settings.precision),
            newValue,
            decimalPart,
            leadingZeros;

        newValue = buildIntegerPart(integerPart, negative, settings);

        if (settings.precision > 0) {
            decimalPart = onlyNumbers.slice(onlyNumbers.length - settings.precision);
            leadingZeros = new Array((settings.precision + 1) - decimalPart.length).join(0);
            newValue += settings.decimal + leadingZeros + decimalPart;
        }
        return setSymbol(newValue, settings);
    }

    function maskValueReverse(value, settings) {
        var negative = (value.indexOf("-") > -1 && settings.allowNegative) ? "-" : "",
            valueWithoutSymbol = value.replace(settings.prefix, "").replace(settings.suffix, ""),
            integerPart = valueWithoutSymbol.split(settings.decimal)[0],
            newValue,
            decimalPart = "";

        if (integerPart === "") {
            integerPart = "0";
        }
        newValue = buildIntegerPart(integerPart, negative, settings);

        if (settings.precision > 0) {
            var arr = valueWithoutSymbol.split(settings.decimal);
            if (arr.length > 1) {
                decimalPart = arr[1];
            }
            newValue += settings.decimal + decimalPart;
            var rounded = Number.parseFloat((integerPart + "." + decimalPart)).toFixed(settings.precision);
            var roundedDecimalPart = rounded.toString().split(settings.decimal)[1];
            newValue = newValue.split(settings.decimal)[0] + "." + roundedDecimalPart;
        }

        return setSymbol(newValue, settings);
    }

    function buildIntegerPart(integerPart, negative, settings) {
        // remove initial zeros
        integerPart = integerPart.replace(/^0*/g, "");

        // put settings.thousands every 3 chars
        integerPart = integerPart.replace(/\B(?=(\d{3})+(?!\d))/g, settings.thousands);
        if (integerPart === "") {
            integerPart = "0";
        }
        return negative + integerPart;
    }

    $.fn.maskMoney = function (method) {
        if (methods[method]) {
            return methods[method].apply(this, Array.prototype.slice.call(arguments, 1));
        } else if (typeof method === "object" || !method) {
            return methods.init.apply(this, arguments);
        } else {
            $.error("Method " + method + " does not exist on jQuery.maskMoney");
        }
    };
})(window.jQuery || window.Zepto);

function reloadAllMasks()
{
  $('.money-mask').trigger('input');
  $('.date-mask').trigger('input');
}

$(document).ready(function(){
  $('.money-mask').mask("#.##0,00", {reverse: true});
  $('.date-mask').mask('00/00/0000', {placeholder: "__/__/____"});
});

$(function () {
    $('.select2').select2();
});

function baseURL( url )
{
  url = url.replace(/^\//, '');
  url = url.replace(/\/$/, '');

  return SearaApp.baseURL + url;
}

function asset( url )
{
  return SearaApp.assetURL + url;
}

$.LoadingOverlaySetup({
  image: SearaApp.assetURL + 'img/ring.svg'
});

/**
 * Object Constructor que encapsula o acesso a recursos no sistema
 * @param {string} resourceURL URL base do recurso
 */
function ResourceModel(resourceURL){
  this.resourceURL = resourceURL;
}

ResourceModel.prototype.create = function (data, callback) {
  return SearaAjax.post( this.resourceURL, data, callback );
};

ResourceModel.prototype.read = function (id, callback) {
  return SearaAjax.get( this.resourceURL + '/' + id, callback );
};

ResourceModel.prototype.update = function (id, data, callback) {
  return SearaAjax.put( this.resourceURL + '/' + id, data, callback );
};

ResourceModel.prototype.delete = function (id, callback) {
  return SearaAjax.delete( this.resourceURL + '/' + id, callback );
};

String.prototype.isEmpty = function() {
    return (this.length === 0 || !this.trim());
};

/**
 * Loader para Seara
 */
var SearaLoader = (function(){

   // Funções para o Loading Overlay
  function showOverlay(sel)
  {
      if ( sel )
      {
          if ( sel.isEmpty() )
              $.LoadingOverlay("show");
          else
              $(sel).LoadingOverlay("show");
      }
      else
          $.LoadingOverlay("show");
  }

  function hideOverlay(sel)
  {
      if ( sel )
      {
          if ( sel.isEmpty() )
              $.LoadingOverlay("hide");
          else
              $(sel).LoadingOverlay("hide");
      }
      else
          $.LoadingOverlay("hide");
  }

  function showModal( title = '' )
  {
    swal({
      title: title,
      imageUrl: asset('img/ring.svg'),
      showConfirmButton: false
    })
  }

  function closeModal()
  {
    swal.close();
  }

  return {
    show: showOverlay,
    hide: hideOverlay,
    showModal: showModal,
    hideModal: closeModal
  }

}());

var SearaAlert = (function(){

  function alertError( title = '', text = '', timer = null )
  {
    return swal({
      title: title,
      text: text,
      type: 'error',
      timer: timer
    });
  }

  function alertSuccess( title = '', text = '', timer = null )
  {
    return swal({
      title: title,
      text: text,
      type: 'success',
      timer: timer
    });
  }

  function confirmAlert(title = '', textConfirm = '', textCancel = '', redirect = '')
  {
    return swal({
      title: title,
      showDenyButton: true,
      showCancelButton: true,
      confirmButtonText: textConfirm,
      denyButtonText: `Don't save`,
      cancelButtonText: textCancel
    }).then((result) => {
      /* Read more about isConfirmed, isDenied below */
      if (result.isConfirmed) {
        console.log({redirect})
        swal('Saved!', '', 'success')
      } else if (result.isDenied) {
        swal('Changes are not saved', '', 'info')
      }
    })
  }

  return {
    error: alertError,
    success: alertSuccess,
    confirm: confirmAlert
  }

}());

var SearaAjax = (function(){
  function getToken()
  {
    return Cookies.get("XSRF-TOKEN");
  }

  function ajaxCall(type, url, data, callback, dataType = 'Json')
  {
    var ajaxOptions = {
      url: baseURL(url),
      headers: { 'X-XSRF-TOKEN': getToken() },
      dataType: dataType,
      type: type,
      method: type
    };

    if ( type == 'POST' || type == 'PUT' )
    {
      if ( data != null )
        ajaxOptions.data = data;
    }

    if ( callback != null )
      ajaxOptions.success = callback;

    return $.ajax( ajaxOptions );

  }

  function postAjax(url, data, callback = null, dataType = 'json')
  {
    return ajaxCall('POST', url, data, callback, dataType);
  }

  function getAjax(url, callback = null, dataType = 'json')
  {
    return ajaxCall('GET', url, null, callback, dataType);
  }

  function deleteAjax(url, callback = null, dataType = 'json')
  {
    return ajaxCall('DELETE', url, null, callback, dataType);
  }

  function putAjax(url, data, callback = null, dataType = 'json')
  {
    return ajaxCall('PUT', url, data, callback, dataType);
  }

  return {
    post: postAjax,
    get: getAjax,
    delete: deleteAjax,
    put: putAjax
  };

}());

function SearaTable(tableID, url, columns, singular = 'registro', plural = 'registros', dataFunc = () => {}){

  this.tableID = tableID;
  this.url = url;
  this.columns = columns;
  this.singular = singular;
  this.plural = plural;
  this.dataFunc = dataFunc;

};

SearaTable.prototype.reloadTable = function() {
  $("#" + this.tableID).DataTable().ajax.reload();
}

SearaTable.prototype.loadTable = function () {
  let thisSearaTable = this;
  let table = $('#'+this.tableID).DataTable({
    processing: true,
    serverSide: true,
    dom: 'lBfrtip',
    lengthMenu: [[10, 25, 50, 100, -1], [10, 25, 50, 100, "Todos"]],
    buttons: [
      {
        extend: 'pdf',
        exportOptions: {
          columns: ':visible'
        }
      },
      {
        extend: 'csv',
        exportOptions: {
          columns: ':visible'
        }
      },
      {
        extend: 'excelHtml5',
        exportOptions: {
          columns: ':visible',
          format: {
            body: function ( data, row, column, node ) {
                if (node.className.split(/\s+/).includes("formatted_number")) {
                    return convertBrCoinToFloat(data);
                }
                return data;
            }
          }
        }
      },
      {
        extend: 'colvis',
        text: 'Selecionar colunas'
      }
    ],
    ajax: {
      url: this.url,
      data: d => {
        d.query = thisSearaTable.dataFunc();
      }
    },
    columns: this.columns,
    language: {
      "lengthMenu": "Exibir _MENU_ " + this.plural + " por página",
      "zeroRecords": "Nenhum " + this.singular + " cadastrado para essa pesquisa",
      "infoEmpty": "Exibindo 0 de 0 " + this.plural,
      "emptyTable": "Nenhum " + this.singular + " cadastrado",
      "info": "Exibindo página _PAGE_ de _PAGES_",
      "infoFiltered": "(filtrados de _MAX_ " + this.plural + ")",
      "search": "Pesquisar:",
      "paginate": {
        "previous": "Anterior",
        "next": "Próximo",
        "first": "Primeiro",
        "last": "Último"
      }
    }
  });

  let selector = $('#company-table_wrapper > div:nth-child(1) > div:nth-child(1)');
  table.buttons().container().appendTo(selector);
};


/**
 * Módulo de notificações com PNotify
 * Esse módulo encapsula diversas funções auxiliares para uso do PNotify
 */
var notify = (function(){

  /**
   * Apresenta uma notificação de sucesso
   * @param  {str} title Título da notificação
   * @param  {str} msg   Mensagem da notificação
   */
  function success(title, msg)
  {
    new PNotify({
      title: title,
      text: msg,
      type: 'success',
      styling: 'bootstrap3'
    });
  }

  /**
   * Apresenta uma notificação de informação
   * @param  {str} title Título da notificação
   * @param  {str} msg   Mensagem da notificação
   */
  function info(title, msg)
  {
    new PNotify({
      title: title,
      text: msg,
      type: 'info',
      styling: 'bootstrap3'
    });
  }

  /**
   * Apresenta uma notificação de aviso
   * @param  {str} title Título da notificação
   * @param  {str} msg   Mensagem da notificação
   */
  function warning(title, msg)
  {
    new PNotify({
      title: title,
      text: msg,
      styling: 'bootstrap3'
    });
  }

  /**
   * Apresenta uma notificação de erro
   * @param  {str} title Título da notificação
   * @param  {str} msg   Mensagem da notificação
   */
  function error(title, msg)
  {
    new PNotify({
      title: title,
      text: msg,
      type: 'error',
      styling: 'bootstrap3'
    });
  }

  /**
   * Apresenta uma notificação baseada na resposta do servidor
   * Caso a requisição tenha tido alguma falha, será apresentada uma
   * notificação de erro, caso contrário, uma notificação de sucesso
   * @param  {json} data Resposta do servidor
   */
  function response(data)
  {
    if (data["status"] == "success") {
      if ( data["message"] instanceof Array )
      {
        for ( message of data["message"] )
          success("Sucesso", message);
      }
      else
        success("Sucesso", data["message"]);
    }
    else {
      if (data["message"] instanceof Array )
      {
        for ( message of data["message"] )
          error("Erro", message);
      }
      else
        error("Erro", data["message"]);
    }
  }

  return {
    success: success,
    error: error,
    info: info,
    warning: warning,
    response: response
  }

})();

/**
 * Resize function without multiple trigger
 * 
 * Usage:
 * $(window).smartresize(function(){  
 *     // code here
 * });
 */
(function($,sr){
    // debouncing function from John Hann
    // http://unscriptable.com/index.php/2009/03/20/debouncing-javascript-methods/
    var debounce = function (func, threshold, execAsap) {
      var timeout;

        return function debounced () {
            var obj = this, args = arguments;
            function delayed () {
                if (!execAsap)
                    func.apply(obj, args); 
                timeout = null; 
            }

            if (timeout)
                clearTimeout(timeout);
            else if (execAsap)
                func.apply(obj, args);

            timeout = setTimeout(delayed, threshold || 100); 
        };
    };

    // smartresize 
    jQuery.fn[sr] = function(fn){  return fn ? this.bind('resize', debounce(fn)) : this.trigger(sr); };

})(jQuery,'smartresize');
